/** Trigger a browser download for generated bytes. */
export function downloadBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  // Give the browser a beat to start the download before revoking.
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

/**
 * Export filename that preserves the imported file's base name — spaces,
 * unicode and all. Only path-hostile characters are replaced, the original
 * extension is dropped, and the extension matching the actual bytes goes on
 * (a .jpg imported and exported as PNG becomes file1.png, not image.png).
 */
export function exportFileName(
  original: string | undefined,
  fallback: string,
  ext: string,
  suffix = '',
): string {
  const base = (original ?? '').replace(/\.[a-z0-9]+$/i, '').trim() || fallback;
  const clean = base.replace(/[/\\:*?"<>|]+/g, '_').slice(0, 120);
  return `${clean}${suffix}.${ext}`;
}
